"""
Online Stock Provider Adapter and Story-Driven Retrieval Engine (ADR-009).
Implements hard constraint filtering, rights eligibility (ELIGIBLE/UNKNOWN/DISALLOWED),
preview-to-acquired asset reconciliation, and story-driven candidate ranking.
"""
import os
import re
import json
import urllib.request
import urllib.parse
from pathlib import Path
from typing import Dict, Any, List, Optional, Tuple

from ...config import BASE_DIR
from ...clip_registry import is_online_id_used, load_registry_lookup
from ...models import RightsStatus

PEXELS_KEY_FILE = BASE_DIR / "AutoVideoPipeline" / "api_keys" / "pexels_api_key.txt"
USER_AGENT = "AutoVideoPipeline/1.0 (Multimedia Production Suite)"


class StockConstraintChecker:
    """Evaluates hard constraints on visual stock candidates."""

    @staticmethod
    def evaluate(
        candidate: Dict[str, Any],
        min_duration: float = 4.0,
        required_orientation: str = "landscape",
        forbidden_terms: Optional[List[str]] = None
    ) -> Tuple[bool, str]:
        # 1. Rights status constraint
        rights = candidate.get("rights_status", RightsStatus.ELIGIBLE.value)
        if rights != RightsStatus.ELIGIBLE.value:
            return False, f"Rights ineligible: status={rights}"

        # 2. Duration constraint
        dur = float(candidate.get("duration", 0.0))
        if dur < min_duration:
            return False, f"Duration too short: {dur:.1f}s < {min_duration:.1f}s"

        # 3. Orientation constraint
        w = candidate.get("width", 1920)
        h = candidate.get("height", 1080)
        if required_orientation == "landscape" and (w and h and w < h):
            return False, f"Orientation invalid: portrait {w}x{h} for landscape requirement"

        # 4. Forbidden content terms
        title = str(candidate.get("title", "")).lower()
        if forbidden_terms:
            for term in forbidden_terms:
                if term.lower() in title:
                    return False, f"Forbidden term found: '{term}' in '{title}'"

        return True, "Passed all hard constraints"


def reconcile_preview_to_final_asset(
    preview_meta: Dict[str, Any],
    final_asset_path: Path,
    duration_tolerance_sec: float = 1.5
) -> Dict[str, Any]:
    """
    Verifies that the downloaded production asset matches the chosen preview candidate.
    Flags ARTIFACT_AMBIGUOUS on material discrepancy.
    """
    if not final_asset_path.exists() or final_asset_path.stat().st_size < 10000:
        return {
            "reconciled": False,
            "status": "NO_MATCH",
            "message": f"Acquired file missing or too small: {final_asset_path}"
        }

    # Verify provider ID correspondence
    expected_id = str(preview_meta.get("id", ""))
    expected_online_id = str(preview_meta.get("online_id", ""))
    actual_path_str = str(final_asset_path).lower()

    id_match = (expected_id and expected_id.lower() in actual_path_str) or \
               (expected_online_id and expected_online_id.lower() in actual_path_str) or \
               preview_meta.get("allow_unnamed_match", False)

    if not id_match:
        return {
            "reconciled": False,
            "status": "ARTIFACT_AMBIGUOUS",
            "message": f"Asset identity mismatch: expected id '{expected_id}' not found in '{final_asset_path.name}'"
        }

    # Verify duration using ffprobe if available
    expected_dur = float(preview_meta.get("duration", 0.0))
    if expected_dur > 0:
        try:
            from ..stage4_render.qa_verifier import QAVerifier
            meta = QAVerifier.inspect_stream_metadata(final_asset_path)
            actual_dur = float(meta.get("duration", 0.0))
            if actual_dur > 0 and abs(actual_dur - expected_dur) > duration_tolerance_sec:
                return {
                    "reconciled": False,
                    "status": "ARTIFACT_AMBIGUOUS",
                    "message": f"Duration drift exceeds tolerance: expected {expected_dur:.1f}s vs actual {actual_dur:.1f}s"
                }
        except Exception:
            pass

    return {
        "reconciled": True,
        "status": "RECONCILED",
        "message": "Production asset reconciled with preview candidate."
    }


class PexelsClient:
    """Pexels Online Stock Provider Adapter."""

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or self._load_key()

    @staticmethod
    def _load_key() -> str:
        if PEXELS_KEY_FILE.exists():
            try:
                k = PEXELS_KEY_FILE.read_text(encoding="utf-8").strip()
                if k:
                    return k
            except Exception:
                pass
        return os.environ.get("PEXELS_API_KEY", "")

    @property
    def is_available(self) -> bool:
        return bool(self.api_key)

    def search_videos(self, query: str, page: int = 1, per_page: int = 12) -> Dict[str, Any]:
        """Searches online stock with zero-reuse filtering and rights tagging."""
        if not self.is_available:
            return {
                "status": "error",
                "message": "Pexels API Key chÆ°a Ä‘Æ°á»£c cÃ i Ä‘áº·t",
                "videos": [],
                "total_results": 0
            }

        clean_query = query.strip()
        if not clean_query:
            return {"status": "ok", "videos": [], "total_results": 0, "page": page}

        params = urllib.parse.urlencode({
            "query": clean_query,
            "page": page,
            "per_page": per_page,
            "orientation": "landscape"
        })
        url = f"https://api.pexels.com/videos/search?{params}"

        req = urllib.request.Request(url, headers={
            "Authorization": self.api_key,
            "User-Agent": USER_AGENT
        })

        try:
            with urllib.request.urlopen(req, timeout=12) as response:
                if response.status != 200:
                    return {"status": "error", "message": f"Pexels Error {response.status}", "videos": [], "total_results": 0}
                data = json.loads(response.read().decode("utf-8"))
        except Exception as e:
            return {"status": "error", "message": f"Pexels Error: {e}", "videos": [], "total_results": 0}

        raw_videos = data.get("videos", [])
        total_results = data.get("total_results", 0)
        lookup = load_registry_lookup()
        filtered_videos = []

        for v in raw_videos:
            v_id = str(v.get("id"))
            online_id = f"pexels_{v_id}"

            if is_online_id_used(online_id, lookup) or is_online_id_used(v_id, lookup):
                continue

            video_files = v.get("video_files", [])
            if not video_files:
                continue

            preview_url = ""
            for vf in sorted(video_files, key=lambda x: x.get("width") or 0):
                if vf.get("quality") == "sd" or (vf.get("width") and vf.get("width") <= 960):
                    preview_url = vf.get("link")
                    break
            if not preview_url and video_files:
                preview_url = video_files[0].get("link")

            download_url = ""
            for vf in sorted(video_files, key=lambda x: x.get("width") or 0, reverse=True):
                if vf.get("quality") == "hd" or (vf.get("width") and vf.get("width") >= 1920):
                    download_url = vf.get("link")
                    break
            if not download_url:
                download_url = preview_url

            user_info = v.get("user", {})
            photographer = user_info.get("name", "Pexels Creator")
            raw_url = v.get("url", "")
            match = re.search(r"/video/([^/]+)-\d+/?", raw_url)
            slug = match.group(1).replace("-", " ").title() if match else f"Clip {v_id}"

            filtered_videos.append({
                "id": v_id,
                "online_id": online_id,
                "title": slug,
                "photographer": photographer,
                "duration": v.get("duration", 0),
                "width": v.get("width", 1920),
                "height": v.get("height", 1080),
                "thumbnail": v.get("image", ""),
                "preview_url": preview_url,
                "download_url": download_url,
                "source": "pexels",
                "rights_status": RightsStatus.ELIGIBLE.value
            })

        return {
            "status": "ok",
            "query": clean_query,
            "page": page,
            "per_page": per_page,
            "total_results": total_results,
            "returned_count": len(filtered_videos),
            "videos": filtered_videos
        }

    def download_video(self, download_url: str, dest_path: Path, timeout: int = 60) -> Path:
        """Downloads the video from the given URL into dest_path."""
        dest_path.parent.mkdir(parents=True, exist_ok=True)
        req = urllib.request.Request(download_url, headers={"User-Agent": USER_AGENT})
        with urllib.request.urlopen(req, timeout=timeout) as response:
            with open(dest_path, "wb") as out_file:
                while True:
                    chunk = response.read(65536)
                    if not chunk:
                        break
                    out_file.write(chunk)
        return dest_path


class StoryStockRetriever:
    """
    High-level story-driven stock retrieval engine.
    Translates narrative VisualRequirement into compiled queries, executes search,
    applies hard constraints and rights rules, and performs layered semantic candidate ranking.
    """

    ABSTRACT_STOPWORDS = {
        "the", "a", "an", "in", "on", "at", "of", "and", "or", "with", "is", "was",
        "for", "to", "from", "by", "about", "into", "through", "during", "before", "after",
        "everything", "something", "nothing", "nothingness", "collapse", "believed",
        "belief", "thought", "felt", "realized", "remembered", "wondered", "became",
        "seemed", "suddenly", "meanwhile", "eventually", "story", "narrative", "scene"
    }

    SEMANTIC_CLUSTERS = {
        "woman": {"woman", "female", "lady", "girl", "person"},
        "man": {"man", "male", "guy", "gentleman", "person"},
        "phone": {"phone", "smartphone", "cellphone", "mobile"},
        "desk": {"desk", "table", "workspace", "office"},
        "street": {"street", "road", "alley", "avenue", "lane"},
        "rain": {"rain", "rainy", "storm", "wet", "downpour"},
        "night": {"night", "dark", "evening", "midnight"},
        "alone": {"alone", "isolated", "solitary", "lonely"},
        "sad": {"sad", "depressed", "dread", "sorrow", "crying", "tearful"},
        "city": {"city", "urban", "skyline", "downtown", "skyscrapers"},
        "courthouse": {"courthouse", "court", "justice", "building", "hall", "corridor"},
        "entrance": {"entrance", "exterior", "steps", "doors", "front", "entry", "facade", "entryway", "outside"}
    }

    CONTRADICTION_PAIRS = [
        ({"rain", "rainy", "storm", "wet"}, {"sunny", "beach", "tropical", "bright"}),
        ({"night", "dark", "midnight"}, {"sunny", "daylight", "bright"}),
        ({"alone", "isolated", "solitary"}, {"crowd", "party", "festival", "celebration"}),
        ({"woman", "female", "lady"}, {"puppies", "dog", "pets", "animals", "basketball"})
    ]

    def __init__(self, provider_client: Optional[PexelsClient] = None):
        self.provider = provider_client or PexelsClient()

    def compile_search_query(self, visual_requirement: Any, narration: str = "") -> str:
        """
        Compiles a visualizable search query from structured VisualRequirement fields
        rather than dumping raw abstract narration.
        """
        terms: List[str] = []

        if isinstance(visual_requirement, str):
            intent_str = visual_requirement
            req_visuals = []
        elif hasattr(visual_requirement, "stock_search_intent") or hasattr(visual_requirement, "required_visuals"):
            intent_str = getattr(visual_requirement, "stock_search_intent", "")
            req_visuals = getattr(visual_requirement, "required_visuals", []) or []
        else:
            intent_str = str(visual_requirement)
            req_visuals = []

        # 1. Include explicit required visuals
        for vis in req_visuals:
            clean_vis = re.sub(r"[^\w\s]", " ", str(vis).lower()).strip()
            for w in clean_vis.split():
                if w not in self.ABSTRACT_STOPWORDS and len(w) > 2 and w not in terms:
                    terms.append(w)

        # 2. Extract visual concepts from stock_search_intent
        clean_intent = re.sub(r"[^\w\s]", " ", intent_str.lower()).strip()
        for w in clean_intent.split():
            if w not in self.ABSTRACT_STOPWORDS and len(w) > 2 and w not in terms:
                terms.append(w)

        # 3. Fallback: if empty, extract concrete nouns from narration
        if not terms and narration:
            clean_narr = re.sub(r"[^\w\s]", " ", narration.lower()).strip()
            for w in clean_narr.split():
                if w not in self.ABSTRACT_STOPWORDS and len(w) > 3 and w not in terms:
                    terms.append(w)

        if not terms:
            return "cinematic atmosphere"

        return " ".join(terms[:5])

    def compute_semantic_similarity(self, candidate: Dict[str, Any], target_intent: str) -> float:
        """
        Layered semantic fit score between candidate metadata and target visual intent.
        Returns a float in [0.0, 1.0].
        """
        clean_intent = re.sub(r"[^\w\s]", " ", target_intent.lower()).strip()
        intent_words = set(w for w in clean_intent.split() if w not in self.ABSTRACT_STOPWORDS and len(w) > 2)

        if not intent_words:
            return 0.5

        cand_text = f"{candidate.get('title', '')} {' '.join(candidate.get('tags', []))} {candidate.get('description', '')}".lower()
        cand_words = set(re.sub(r"[^\w\s]", " ", cand_text).split())

        has_contradiction = False
        for set_a, set_b in self.CONTRADICTION_PAIRS:
            if (intent_words & set_a) and (cand_words & set_b):
                has_contradiction = True
                break
            if (intent_words & set_b) and (cand_words & set_a):
                has_contradiction = True
                break

        direct_matches = intent_words & cand_words
        match_count = float(len(direct_matches))

        for iw in intent_words:
            if iw in direct_matches:
                continue
            for root, cluster in self.SEMANTIC_CLUSTERS.items():
                if iw in cluster and (cand_words & cluster):
                    match_count += 0.8
                    break

        raw_score = match_count / len(intent_words)
        score = min(1.0, max(0.0, raw_score))

        if has_contradiction:
            score = score * 0.15

        return round(score, 3)

    def rank_candidates(
        self,
        candidates: List[Dict[str, Any]],
        target_intent: str,
        target_duration: float = 5.0
    ) -> List[Dict[str, Any]]:
        """
        Layered candidate evaluation:
        1. Hard Eligibility
        2. Narrative / Visual Semantic Fit (dominant weight)
        3. Editorial Utility (duration sufficiency)
        Returns ranked candidates with transparent 'semantic_score' and 'editorial_utility'.
        """
        scored_candidates: List[Dict[str, Any]] = []

        for cand in candidates:
            sem_score = self.compute_semantic_similarity(cand, target_intent)

            dur = float(cand.get("duration", 0.0))
            if target_duration > 0:
                if dur >= target_duration:
                    ed_score = 1.0
                else:
                    ed_score = max(0.2, dur / target_duration)
            else:
                ed_score = 1.0

            if sem_score < 0.20:
                final_score = sem_score * 0.5
            else:
                final_score = (sem_score * 0.85) + (ed_score * 0.15)

            c_copy = dict(cand)
            c_copy["semantic_score"] = sem_score
            c_copy["editorial_utility"] = round(ed_score, 2)
            c_copy["final_rank_score"] = round(final_score, 3)
            scored_candidates.append(c_copy)

        scored_candidates.sort(key=lambda c: c["final_rank_score"], reverse=True)
        return scored_candidates

    def retrieve_candidates_for_requirement(
        self,
        intent: str,
        min_duration: float = 5.0,
        forbidden_terms: Optional[List[str]] = None,
        max_candidates: int = 3
    ) -> Dict[str, Any]:
        """
        Executes query compilation -> search -> constraint check -> shortlist ranking.
        """
        search_query = self.compile_search_query(intent)

        raw_res = self.provider.search_videos(search_query, per_page=12)
        if raw_res.get("status") != "ok":
            return {
                "disposition": "NO_MATCH",
                "message": f"Provider search failed: {raw_res.get('message')}",
                "candidates": []
            }

        candidates = raw_res.get("videos", [])
        eligible: List[Dict[str, Any]] = []

        for cand in candidates:
            ok, reason = StockConstraintChecker.evaluate(
                cand,
                min_duration=min_duration,
                forbidden_terms=forbidden_terms
            )
            if ok:
                eligible.append(cand)

        ranked = self.rank_candidates(eligible, target_intent=intent, target_duration=min_duration)
        bounded_proposals = ranked[:max_candidates]

        if not bounded_proposals:
            return {
                "disposition": "NO_MATCH",
                "message": f"Zero eligible candidates satisfied hard constraints for intent '{search_query}'",
                "candidates": []
            }

        top_candidate = bounded_proposals[0]
        sem_score = top_candidate.get("semantic_score", 0.0)
        if sem_score >= 0.40:
            disposition = "AUTO_SELECT"
        elif sem_score >= 0.15:
            disposition = "OWNER_REVIEW"
        else:
            disposition = "NO_MATCH"

        return {
            "disposition": disposition,
            "query_compiled": search_query,
            "total_evaluated": len(candidates),
            "candidates": bounded_proposals,
            "selected_candidate": top_candidate if disposition == "AUTO_SELECT" else None
        }
"""
Scene planner and narrative partitioner for videopipeline.
"""
from typing import List, Dict, Any
from pathlib import Path
from ...models import SubtitleCue, StoryChapter
from ...config import F2_CHAPTER1_DURATION, F2_SEGMENT_DURATION

def plan_story_scenes(total_duration: float, cues: List[SubtitleCue]) -> Dict[str, Any]:
    """
    Plans the structural breakdown of a story video:
    - Chapter 1: 0 to 180s (hook & opening)
    - Body: 180s to total_duration (alternating 30s slots)
    """
    body_duration = max(0.0, total_duration - F2_CHAPTER1_DURATION)
    
    # Calculate how many 30s segments are needed for the body
    num_body_segments = int(body_duration // F2_SEGMENT_DURATION)
    remainder = body_duration % F2_SEGMENT_DURATION
    if remainder > 3.0:
        num_body_segments += 1

    # Slots alternate: Stock -> AI -> Stock -> AI...
    stock_slots = (num_body_segments + 1) // 2
    ai_slots = num_body_segments // 2

    return {
        "total_duration": total_duration,
        "chapter1_duration": min(total_duration, F2_CHAPTER1_DURATION),
        "body_duration": body_duration,
        "num_body_segments": num_body_segments,
        "stock_slots_required": stock_slots,
        "ai_slots_required": ai_slots,
        "cue_count": len(cues)
    }
