        if not self.format_plan_fingerprint and self.format_plan:
            self.format_plan_fingerprint = self.format_plan.fingerprint
        if self.effect_profile is None:
            self.effect_profile = self.format_plan.effect_profile
        if not self.effect_profile_fingerprint and self.effect_profile:
            self.effect_profile_fingerprint = self.effect_profile.fingerprint
        if self.layout_profile is None and self.format_id == FormatId.F4:
            self.layout_profile = self.format_plan.layout_profile
        if not self.fingerprint:
            raw = (
                f"{self.story_dir.name}_{self.format_id.value}_"
                f"{self.format_plan_fingerprint}_{self.creative_plan_fingerprint}_"
                f"{self.editorial_timeline_fingerprint}_{self.effect_profile_fingerprint}"
            )
            self.fingerprint = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


@dataclass
class RunManifest:
    """Proof of execution capturing full lineage, format validation, and media hashes."""
    run_id: str
    timestamp: str = ""
    story_name: str = ""
    format_id: str = ""
    creative_plan_fingerprint: str = ""
    format_plan_fingerprint: str = ""
    editorial_timeline_fingerprint: str = ""
    compose_plan_fingerprint: str = ""
    effect_profile_fingerprint: str = ""
    editorial_qc_verdict: str = "PASS"
    owner_disposition: str = "AUTO"
    output_file: str = ""
    output_sha256: str = ""
    assets_used: List[Dict[str, Any]] = field(default_factory=list)
    redacted: bool = True

    def to_dict(self) -> Dict[str, Any]:
        from .secret_redactor import redact_data
        d = asdict(self)
        return redact_data(d)

    def validate_lineage(self, strict: bool = True) -> bool:
        """Validates that all five required canonical lineage fingerprints are present and non-empty.
        
        Mandatory lineage fingerprints:
        - creative_plan_fingerprint
        - format_plan_fingerprint
        - editorial_timeline_fingerprint
        - compose_plan_fingerprint
        - effect_profile_fingerprint

        If strict=True and any required fingerprint is missing or empty, raises ValueError.
        Returns True if all five fingerprints are valid, False otherwise.
        """
        required_fields = [
            "creative_plan_fingerprint",
            "format_plan_fingerprint",
            "editorial_timeline_fingerprint",
            "compose_plan_fingerprint",
            "effect_profile_fingerprint"
        ]
        missing = [f for f in required_fields if not getattr(self, f, None) or not str(getattr(self, f)).strip()]
        if missing:
            if strict:
                raise ValueError(
                    f"LINEAGE_VALIDATION_ERROR: Missing required lineage fingerprints in RunManifest: {', '.join(missing)}"
                )
            return False
        return True

    @property
    def is_lineage_valid(self) -> bool:
        """Returns True if all 5 mandatory canonical lineage fingerprints are present."""
        return self.validate_lineage(strict=False)


